def safe_url(value):
    try:
        u=urllib.parse.urlsplit(str(value))
        if u.scheme not in ('http','https') or not u.hostname or u.username or u.password:return None
        host=u.hostname
        if host in ('localhost',) or host.endswith(('.local','.internal','.localhost')):return None
        try:
            if not ipaddress.ip_address(host).is_global:return None
        except ValueError:
            if '.' not in host:return None
        return urllib.parse.urlunsplit(u)
    except ValueError:return None
def server_origin(value):
    valid=safe_url(value)
    if not valid:return None
    u=urllib.parse.urlsplit(valid)
    return urllib.parse.urlunsplit((u.scheme,u.netloc,'','',''))
def playlist_url(c):return c['server'].rstrip('/')+'/get.php?'+urllib.parse.urlencode({'username':c['username'],'password':c['password'],'type':'m3u_plus','output':'mpegts'})
def provider_json(c,action=None,params=None):
    # Mesmo transporte da base fornecida: urllib, User-Agent IPTV e redirects normais.
    fields={'username':c['username'],'password':c['password']}
    if action:fields['action']=action
    fields.update(params or {})
    url=c['server'].rstrip('/')+'/player_api.php?'+urllib.parse.urlencode(fields)
    req=urllib.request.Request(url,headers={'User-Agent':'IPTVSmartersPro/3.1.5 (Linux; Android 12)','Accept':'*/*'})
    with urllib.request.urlopen(req,timeout=8,context=SSL_CTX) as response:
        return json.loads(response.read(48000000).decode('utf-8','replace'))
def verify_m3u(c):
    req=urllib.request.Request(playlist_url(c),headers={'User-Agent':'IPTVSmartersPro/3.1.5 (Linux; Android 12)','Accept':'*/*'})
    with urllib.request.urlopen(req,timeout=12,context=SSL_CTX) as response:
        text=response.read(32768).decode('utf-8','replace')
        return text.lstrip('\ufeff \r\n').startswith('#EXTM3U') and '#EXTINF' in text

def iso(value):return datetime.fromtimestamp(value/1000,timezone.utc).isoformat() if value else None
def timestamp(value):
    if value is None or value=='':return None
    try:
        if str(value).isdigit():
            n=int(value);return n if n>10**12 else n*1000
        text=str(value).strip().replace(' às ',' ').replace('Z','+00:00')
        if re.match(r'^\d{2}/\d{2}/\d{4}',text):
            date=datetime.strptime(text[:19],'%d/%m/%Y %H:%M:%S') if len(text)>=19 else datetime.strptime(text[:16],'%d/%m/%Y %H:%M')
        else:date=datetime.fromisoformat(text)
        if date.tzinfo is None:date=date.replace(tzinfo=timezone(timedelta(hours=-3)))
        return int(date.timestamp()*1000)
    except (ValueError,TypeError,OverflowError):return None

def allowed(a):return bool(a and not a['revoked'] and (a['provider_status']=='Active' or a['provider_status']=='External' and not a['is_trial']) and (not a['expires_at'] or a['expires_at']>now()) and (not a['is_trial'] or a['trial_deadline'] and a['trial_deadline']>now()))
