    port=int(os.environ.get('NEXO_PORT',os.environ.get('PORT','8088')))
    host=os.environ.get('NEXO_HOST','0.0.0.0')
    print(f'Nexo Play: http://{host}:{port} • Admin: /admin',flush=True)
    print(f'Dados persistentes: {DATA}',flush=True)
    if (DATA/'admin-inicial.txt').exists():print('Usuário inicial: admin • senha no arquivo privado admin-inicial.txt dentro da pasta de dados.',flush=True)
    serve(app,host=host,port=port,threads=12,ident='NexoPlay',clear_untrusted_proxy_headers=False)
